
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_cam_qtp_00_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cam_qtp_00", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.998080342777254e+00, -1.960126272058299e+00, -1.906959468168157e+00, -1.833342366060254e+00, -1.733092395879853e+00, -1.599782159369883e+00, -1.428376635331273e+00, -1.218067119575782e+00, -9.755899429070530e-01, -7.154156797462564e-01, -4.569415012696104e-01, -3.030502081547728e-01, -2.591537303718726e-01, -2.064293478095200e-01, -1.329448153489855e-01, -5.956516357097362e-02, -1.762983114142442e-02, -1.105999202624065e-02, -6.007981780441339e-03, -3.820233180461164e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


